<?php require_once __DIR__.'/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email']];if($u['is_admin'])$_SESSION['admin']=true;redirect($u['is_admin']?'admin/index.php':'index.php');}flash('Invalid email or password.','danger');} header_html('Login'); ?><main class="container py-5" style="max-width:520px"><div class="card shadow-sm"><div class="card-body p-4"><h1>Welcome back</h1><p class="text-secondary">Sign in to manage your reservations.</p><form method="post"><label class="form-label">Email</label><input type="email" name="email" class="form-control mb-3" required><label class="form-label">Password</label><input type="password" name="password" class="form-control mb-3" required><button class="btn btn-gold w-100">Login</button></form><p class="mt-3 mb-0">No account? <a href="register.php">Register</a></p></div></div></main><?php footer_html(); ?>